def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    total_agents = 1 + len(alive_opponents)
    expected_total_need = total_agents * WATER_REQ
    scarcity = supply < expected_total_need

    highest_prev_bid = 0
    urgent_opp_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp_count += 1
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid')
        if isinstance(prev_bid, (int, float)) and prev_bid > highest_prev_bid:
            highest_prev_bid = prev_bid

    my_urgent = hp <= 3 or no_water_days >= 1

    if my_urgent:
        base = DAILY_SALARY * 0.92
        if scarcity:
            base = max(base, highest_prev_bid + 2)
        bid = base
    else:
        if not scarcity:
            bid = DAILY_SALARY * 0.34
            if highest_prev_bid > 0 and highest_prev_bid < DAILY_SALARY * 0.45:
                bid = max(bid, highest_prev_bid + 1)
        else:
            pressure = 0.58 + 0.07 * urgent_opp_count
            if hp >= 7 and no_water_days == 0:
                pressure -= 0.06
            bid = DAILY_SALARY * pressure
            if highest_prev_bid > 0:
                if highest_prev_bid >= DAILY_SALARY * 0.9:
                    bid = min(bid, DAILY_SALARY * 0.72)
                else:
                    bid = max(bid, highest_prev_bid + 1.5)

    if hp <= 2:
        bid = max(bid, DAILY_SALARY * 0.96)
    elif hp >= 8 and no_water_days == 0 and not scarcity:
        bid = min(bid, DAILY_SALARY * 0.28)

    if budget < bid:
        bid = budget

    if bid < 0:
        bid = 0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    budget = float(my_status.get('budget', 0.0))
    hp = int(my_status.get('hp', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((opp_id, o))

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Immediate reaction from yesterday traces
    prev_bids = []
    prev_pressures = []
    for _, o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass
        # Use their previous hp_after/status if available to infer pressure
        hp_after = prev.get('hp_after', None)
        status = prev.get('status', None)
        if hp_after is not None:
            try:
                prev_pressures.append((float(hp_after), status))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply-based aggressiveness: lower supply -> higher chance of scarcity -> bid more
    # Convert to a 0..1 scarcity factor
    if MAX_SUPPLY <= MIN_SUPPLY:
        scarcity = 0.5
    else:
        scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
        if scarcity < 0.0:
            scarcity = 0.0
        if scarcity > 1.0:
            scarcity = 1.0

    # Base bid aiming to secure enough water without overspending
    # Target: around 1 water unit when possible; scale by scarcity and competition.
    # Since bids are abstract, map to budget fraction.
    base_fraction = 0.35 + 0.25 * scarcity

    # If we are in danger (many no-water days or low hp), increase bid.
    if hp <= 2 or no_water_days >= 2:
        base_fraction += 0.35
    elif hp <= 3:
        base_fraction += 0.15

    # If opponents were already bidding high yesterday, counter.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if hp > 3:
            base_fraction += 0.10
        else:
            base_fraction += 0.25
    elif highest_prev_bid >= DAILY_SALARY * 0.60:
        base_fraction += 0.05

    # Convert fraction to an actual bid, capped by budget.
    bid = budget * base_fraction

    # Additional cap to avoid extreme overbids; still responsive to competition.
    # Keep bid within [0.2*salary, 1.0*salary] adjusted by scarcity.
    min_bid = DAILY_SALARY * (0.20 + 0.10 * scarcity)
    max_bid = DAILY_SALARY * (1.00 if scarcity >= 0.5 else 0.85)

    if bid < min_bid:
        bid = min_bid
    if bid > max_bid:
        bid = max_bid

    # Final safety: cannot exceed budget
    if bid > budget:
        bid = budget

    # If budget is tiny, just bid what we can.
    if bid < 0.0:
        bid = 0.0

    return float(bid)
